  ('apchem-frq-l-010', '0f82fc0e-0556-4279-a087-a147c9938f74'::uuid, '905a03d4-5024-4f6d-af04-041ff3fb4e61'::uuid, '2ee239e1e2ced2b2839aeedc28689bbbeeeadd215a435aa4e5aad83bf447ed14', array[2,3]::integer[], 2, '[{"criterion_key":"a1","units":[2],"evidence":"Describing NaCl(s) as an alternating 3-D lattice of Na+ and Cl- ions held by electrostatic attractions is Unit 2 structure of ionic solids."},{"criterion_key":"b1","units":[2,3],"evidence":"Explaining brittleness from shifted ionic layers and like-charge repulsions requires ionic lattice/charge-interaction structure from Unit 2 and properties of ionic solids from Unit 3."},{"criterion_key":"c1","units":[2,3],"evidence":"The electron-sea model and metallic bonding/alloy structure are Unit 2; using nondirectional metallic bonding to explain malleability is a scored solid-property explanation from Unit 3."},{"criterion_key":"d1","units":[2,3],"evidence":"Substitutional Zn atoms in a Cu lattice are alloy-structure content from Unit 2, while the effect on hardness/malleability is a property-of-solids/alloys explanation from Unit 3."},{"criterion_key":"e1","units":[3],"evidence":"Contrasting immobile ions in solid NaCl with mobile ions in molten NaCl as the basis for electrical conductivity is Unit 3 ionic-solid property content."},{"criterion_key":"f1","units":[3],"evidence":"Explaining aqueous NaCl conductivity by dissociation into mobile hydrated ions is Unit 3 solution/mixture and ionic-solid conductivity content."}]'::jsonb, 'cbe3116f-6ef5-410c-b535-e9fb711c4c2c'::uuid, 'provisional_model', '{"run_id":"serving-units-mcp-2026-09-25-20260925203431","reason":"two_model_unit_agreement_no_usable_legacy","scope":"serving_only","coverage_deferred":true,"model_results_file":"/private/tmp/cramapple-math-taxonomy-serving/model_results.json"}'::jsonb, 'serving-units-mcp-2026-09-25-20260925203431', 'ee24c8a28267fc99998bfe9e754352a24596a067cee5e5a2c255bc204f303a96'),
